style.css:
@-moz-document domain("youtube.com") {
:root {
    --bg: #ffffff;
    --surface: #ffffff;
    --surface2: #f9f9f9;
    --text: #0f0f0f;
    --secondary: #606060;
    --border: #e5e5e5;
    --hover: #f2f2f2;
    --blue: #065fd4;
}

html[dark] {
    --bg: #0f0f0f;
    --surface: #0f0f0f;
    --surface2: #181818;
    --text: #ffffff;
    --secondary: #aaaaaa;
    --border: #303030;
    --hover: #272727;
    --blue: #3ea6ff;
}

html,
body,
ytd-app,
#page-manager,
#content,
#columns,
ytd-browse,
ytd-search,
ytd-watch-flexy {
    background: var(--bg) !important;
    color: var(--text) !important;
}

#masthead-container,
#masthead,
ytd-masthead,
#container.ytd-masthead {
    background: var(--surface) !important;
    color: var(--text) !important;
}

#guide,
#guide-inner,
#guide-content,
ytd-guide-renderer {
    background: var(--surface) !important;
    color: var(--text) !important;
}

ytd-guide-entry-renderer,
ytd-guide-entry-renderer tp-yt-paper-item {
    background: transparent !important;
    color: var(--text) !important;
}

ytd-guide-entry-renderer:hover,
ytd-guide-entry-renderer[active] {
    background: var(--hover) !important;
}

#container.ytd-searchbox {
    background: var(--bg) !important;
    border: 1px solid #c6c6c6 !important;
    border-radius: 2px !important;
}

html[dark] #container.ytd-searchbox {
    background: #121212 !important;
    border-color: #303030 !important;
}

#search-input {
    background: transparent !important;
    color: var(--text) !important;
}

#search-input::placeholder {
    color: var(--secondary) !important;
}

#search-icon-legacy {
    background: var(--surface2) !important;
    border: 1px solid var(--border) !important;
    color: var(--text) !important;
}

#chips-wrapper,
#chips-content,
ytd-feed-filter-chip-bar-renderer {
    background: var(--bg) !important;
}

yt-chip-cloud-chip-renderer {
    background: var(--surface2) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
    border-radius: 16px !important;
}

yt-chip-cloud-chip-renderer:hover {
    background: var(--hover) !important;
}

ytd-rich-grid-renderer,
ytd-rich-grid-row,
ytd-rich-item-renderer,
ytd-grid-video-renderer,
ytd-video-renderer {
    background: transparent !important;
    color: var(--text) !important;
}

#contents.ytd-rich-grid-renderer {
    background: var(--bg) !important;
}

#video-title,
#video-title-link {
    color: var(--text) !important;
}

#metadata-line,
#metadata-line span,
ytd-video-meta-block,
#channel-name {
    color: var(--secondary) !important;
}

#primary,
#primary-inner,
#secondary,
#secondary-inner {
    background: var(--bg) !important;
    color: var(--text) !important;
}

h1.title,
ytd-watch-metadata h1 {
    color: var(--text) !important;
}

#info,
#info-container,
#info-contents,
#count {
    color: var(--secondary) !important;
}

ytd-toggle-button-renderer,
ytd-menu-renderer,
ytd-button-renderer {
    color: var(--text) !important;
}

ytd-toggle-button-renderer:hover,
ytd-button-renderer:hover {
    background: var(--hover) !important;
}

ytd-compact-video-renderer {
    background: transparent !important;
    color: var(--text) !important;
}

ytd-compact-video-renderer #video-title {
    color: var(--text) !important;
}

ytd-compact-video-renderer #metadata-line,
ytd-compact-video-renderer #metadata-line span {
    color: var(--secondary) !important;
}

ytd-comments,
ytd-comment-thread-renderer,
ytd-comment-renderer {
    background: var(--bg) !important;
    color: var(--text) !important;
}

#content-text,
#author-text,
#header-author {
    color: var(--text) !important;
}

#published-time-text {
    color: var(--secondary) !important;
}

ytd-c4-tabbed-header-renderer,
ytd-channel-header-renderer,
#channel-header {
    background: var(--bg) !important;
    color: var(--text) !important;
}

#subscriber-count {
    color: var(--secondary) !important;
}

tp-yt-paper-tab {
    color: var(--secondary) !important;
    background: transparent !important;
}

tp-yt-paper-tab.iron-selected,
tp-yt-paper-tab.iron-selected #tab-title {
    color: var(--text) !important;
}

ytd-subscribe-button-renderer tp-yt-paper-button {
    background: #ff0000 !important;
    color: #ffffff !important;
    border-radius: 2px !important;
}

ytd-subscribe-button-renderer[subscribed] tp-yt-paper-button {
    background: var(--hover) !important;
    color: var(--text) !important;
}

ytd-rich-shelf-renderer,
ytd-reel-shelf-renderer,
ytd-shelf-renderer {
    background: var(--bg) !important;
    color: var(--text) !important;
}

tp-yt-paper-dialog,
tp-yt-paper-listbox,
ytd-popup-container,
ytd-menu-popup-renderer {
    background: var(--surface) !important;
    color: var(--text) !important;
}

tp-yt-paper-item {
    background: transparent !important;
    color: var(--text) !important;
}

tp-yt-paper-item:hover {
    background: var(--hover) !important;
}

#movie_player,
.html5-video-player,
.html5-video-container,
video {
    background: #000000 !important;
}

#shorts-container {
    background: #000000 !important;
}

ytd-shorts,
ytd-shorts-page {
    background: #000000 !important;
    color: #ffffff !important;
}

ytd-shorts #page-manager,
ytd-shorts #content,
ytd-shorts #columns,
ytd-shorts #primary {
    background: #000000 !important;
}

ytd-shorts #secondary,
ytd-shorts #secondary-inner {
    background: #000000 !important;
}

ytd-shorts ytd-masthead,
ytd-shorts #masthead-container {
    background: #ffffff !important;
    color: #0f0f0f !important;
}

ytd-reel-video-renderer {
    background: #000000 !important;
    color: #ffffff !important;
}

ytd-reel-video-renderer #player-container,
ytd-reel-video-renderer #shorts-player,
ytd-reel-video-renderer #player {
    background: #000000 !important;
}

ytd-reel-video-renderer #overlay,
ytd-reel-video-renderer #details,
ytd-reel-video-renderer #meta {
    color: #ffffff !important;
}

ytd-reel-video-renderer #title,
ytd-reel-video-renderer #description,
ytd-reel-video-renderer #channel-name,
ytd-reel-video-renderer #author-text {
    color: #ffffff !important;
}

ytd-reel-video-renderer #metadata,
ytd-reel-video-renderer #metadata-line {
    color: #aaaaaa !important;
}

ytd-reel-video-renderer #actions,
ytd-reel-video-renderer #actions-inner {
    background: transparent !important;
}

ytd-reel-video-renderer #actions yt-icon,
ytd-reel-video-renderer #actions button,
ytd-reel-video-renderer #button-bar yt-icon {
    color: #ffffff !important;
}

ytd-reel-video-renderer #like-button,
ytd-reel-video-renderer #dislike-button,
ytd-reel-video-renderer #share-button,
ytd-reel-video-renderer #menu-button {
    background: transparent !important;
    color: #ffffff !important;
}

ytd-reel-video-renderer #like-button:hover,
ytd-reel-video-renderer #dislike-button:hover,
ytd-reel-video-renderer #share-button:hover,
ytd-reel-video-renderer #menu-button:hover {
    background: #272727 !important;
}

ytd-reel-video-renderer ytd-comments,
ytd-reel-video-renderer #comments {
    background: #ffffff !important;
    color: #0f0f0f !important;
}

ytd-reel-video-renderer ytd-comments *,
ytd-reel-video-renderer #comments * {
    color: #0f0f0f !important;
}

ytd-reel-shelf-renderer {
    background: #000000 !important;
    color: #ffffff !important;
}

ytd-reel-shelf-renderer #contents {
    background: #000000 !important;
}

ytd-shorts ::-webkit-scrollbar {
    width: 8px !important;
}

ytd-shorts ::-webkit-scrollbar-track {
    background: #000000 !important;
}

ytd-shorts ::-webkit-scrollbar-thumb {
    background: #606060 !important;
}
}
